let localInvitations=[];try{localInvitations=JSON.parse(localStorage.getItem('homework-admin-invites')||'[]')}catch{}
function adminId(){return cloud.ready?cloud.user.id:role==='admin'?'admin-demo':school.managerId}
function canAdminSchool(schoolId=activeSchoolId()){return role==='admin'||role==='manager'&&school.staff.some(s=>s.schoolId===schoolId&&s.userId===adminId()&&s.role==='manager')}
function invitationExpired(invite,now=Date.now()){return new Date(invite.expires_at).getTime()<=now}
function invitationUrl(invite){return location.origin+location.pathname+'#invite='+invite.token}
function saveLocalInvites(){localStorage.setItem('homework-admin-invites',JSON.stringify(localInvitations))}
async function redeemPendingInvitation(){const raw=location.hash.match(/^#invite=([0-9a-f-]{36})$/i)?.[1]||sessionStorage.getItem('pendingSchoolInvite');if(!raw||!cloud.user)return;try{await cloudResult(cloud.client.rpc('accept_school_invitation',{invitation_token:raw}));cloud.pendingInviteError=null;sessionStorage.removeItem('pendingSchoolInvite');history.replaceState(null,'',location.pathname+location.search);return true}catch(e){cloud.pendingInviteError=e.message;return false}}
const incomingInvitation=location.hash.match(/^#invite=([0-9a-f-]{36})$/i)?.[1];if(incomingInvitation){sessionStorage.setItem('pendingSchoolInvite',incomingInvitation);cloudMessage('קיבלת הזמנה. הירשמו או היכנסו עם האימייל שאליו נשלחה ואשרו את כתובת האימייל. ההזמנה תשויך לאחר הכניסה.');}
function fillAdminSelect(select,items,selected){select.replaceChildren();for(const item of items){const option=el('option',item.name);option.value=item.id;select.append(option)}if(items.some(x=>x.id===selected))select.value=selected}
function renderInviteStudents(){const classId=document.getElementById('inviteClass').value;fillAdminSelect(document.getElementById('inviteStudent'),school.students.filter(s=>s.classIds.includes(classId)),activeStudentId());document.getElementById('inviteStudentLabel').hidden=document.getElementById('inviteRole').value!=='parent'}
document.getElementById('inviteClass').onchange=renderInviteStudents;document.getElementById('inviteRole').onchange=renderInviteStudents;
function renderAdmin(){if(typeof renderManagement==='function')renderManagement();if(typeof renderRoleManagement==='function')renderRoleManagement();if(typeof renderPermissions==='function')renderPermissions();const managed=['admin','manager'].includes(role);for(const selector of ['main .top','main .stats','main .layout','#questionsPanel']){const item=document.querySelector(selector);if(item)item.style.display=managed?'none':''}const panel=document.getElementById('adminDashboard');panel.hidden=!['admin','manager'].includes(role);if(panel.hidden)return;document.getElementById('adminTitle').textContent=role==='admin'?'אדמין — הקמת תשתית ועריכת בתי ספר':'מנהל בית ספר — כיתות, צוות והורים';document.getElementById('systemSetup').hidden=role!=='admin';document.getElementById('adminSchoolName').value=activeSchool()?.name||'';document.getElementById('adminClassName').value=school.classes.find(c=>c.id===activeClassId())?.name||'';const staffTeachers=school.teachers.filter(t=>school.staff.some(s=>s.schoolId===activeSchoolId()&&s.userId===t.id&&s.role==='teacher')||t.classIds.some(id=>school.classes.some(c=>c.id===id&&c.schoolId===activeSchoolId())));fillAdminSelect(document.getElementById('adminClassTeacher'),staffTeachers,'');fillAdminSelect(document.getElementById('inviteClass'),[{id:'',name:'ללא כיתה — צוות בית הספר'},...school.classes.filter(c=>c.schoolId===activeSchoolId())],activeClassId());renderInviteStudents();document.querySelector('#inviteRole option[value="manager"]').disabled=role!=='admin';if(role!=='admin'&&document.getElementById('inviteRole').value==='manager')document.getElementById('inviteRole').value='teacher';const list=document.getElementById('invitationList');list.replaceChildren();const invites=(cloud.ready?cloud.invitations:localInvitations).filter(i=>i.school_id===activeSchoolId());for(const invite of invites){const row=el('div',null,'notice');const state=invitationExpired(invite)&&invite.status==='pending'?'פג תוקף':{pending:'ממתינה להצטרפות',accepted:'התקבלה',revoked:'בוטלה'}[invite.status];row.append(el('b',invite.email),el('p',({teacher:'מורה',parent:'הורה',student:'תלמיד',manager:'מנהל בית ספר'}[invite.invite_role])+' · '+state));if(invite.status==='pending'&&!invitationExpired(invite)){const url=invitationUrl(invite),link=el('input');link.value=url;link.readOnly=true;link.dir='ltr';link.setAttribute('aria-label','קישור הזמנה');row.append(link);const copy=el('button','העתקת קישור','secondary');copy.type='button';copy.onclick=async()=>{try{await navigator.clipboard.writeText(url);document.getElementById('adminStatus').textContent='הקישור הועתק.'}catch{link.select();document.getElementById('adminStatus').textContent='העתיקו את הקישור המסומן.'}};const email=el('a','פתיחת אימייל לשליחה');email.href='mailto:'+invite.email+'?subject='+encodeURIComponent('הזמנה ל־Nohomework — '+activeSchool().name)+'&body='+encodeURIComponent('שלום, הוזמנת להצטרף ל־Nohomework. פתחו את הקישור, הירשמו ואשרו את האימייל שאליו נשלחה ההזמנה:\n'+url+'\nהקישור תקף לשבעה ימים.');const revoke=el('button','ביטול הזמנה','secondary');revoke.type='button';revoke.onclick=async()=>{try{if(!canAdminSchool(invite.school_id))throw new Error('אין הרשאה.');if(cloud.ready){await cloudResult(cloud.client.rpc('revoke_school_invitation',{invitation_id:invite.id}));await cloudRefresh()}else{invite.status='revoked';saveLocalInvites();renderAdmin()}}catch(e){document.getElementById('adminStatus').textContent=e.message}};row.append(copy,email,revoke)}list.append(row)}if(!invites.length)list.append(el('p','אין עדיין הזמנות לבית הספר הנבחר.'));}
async function adminOperation(action){const status=document.getElementById('adminStatus');try{await action();if(cloud.ready)await cloudRefresh();else{saveSchool();render()}status.textContent='✓ השינוי נשמר.'}catch(e){status.textContent='הפעולה לא הושלמה: '+e.message}}
document.getElementById('adminCreateSchool').onclick=()=>adminOperation(async()=>{if(role!=='admin')throw new Error('רק אדמין יכול להקים בית ספר.');const name=document.getElementById('adminNewSchool').value.trim();if(!name)throw new Error('הוסיפו שם.');if(cloud.ready){const row=await cloudResult(cloud.client.from('school_schools').insert({name,owner_teacher_id:cloud.user.id}).select('id').single());school.schoolId=row.id}else{const id=crypto.randomUUID();school.schools.push({id,name,ownerId:adminId()});school.schoolId=id;}school.classId='';document.getElementById('adminNewSchool').value=''});
document.getElementById('adminRenameSchool').onclick=()=>adminOperation(async()=>{if(!canAdminSchool())throw new Error('אין הרשאה לבית הספר.');const name=document.getElementById('adminSchoolName').value.trim();if(!name)throw new Error('הוסיפו שם.');if(cloud.ready)await cloudResult(cloud.client.from('school_schools').update({name}).eq('id',activeSchoolId()));else activeSchool().name=name});
document.getElementById('adminRenameClass').onclick=()=>adminOperation(async()=>{if(!canAdminSchool()||!activeClassId())throw new Error('בחרו כיתה מורשית.');const name=document.getElementById('adminClassName').value.trim();if(!name)throw new Error('הוסיפו שם.');if(cloud.ready)await cloudResult(cloud.client.from('school_classes').update({name}).eq('id',activeClassId()));else school.classes.find(c=>c.id===activeClassId()).name=name});
document.getElementById('adminCreateClass').onclick=()=>adminOperation(async()=>{if(!canAdminSchool()||!activeSchoolId())throw new Error('בחרו בית ספר מורשה.');const name=document.getElementById('adminNewClass').value.trim(),teacherId=document.getElementById('adminClassTeacher').value;if(!name||!teacherId)throw new Error('נדרשים שם כיתה ומורה משויך לבית הספר. הזמינו מורה תחילה.');if(cloud.ready)await cloudResult(cloud.client.from('school_classes').insert({name,school_id:activeSchoolId(),owner_teacher_id:teacherId}));else{const id=crypto.randomUUID();school.classes.push({id,name,schoolId:activeSchoolId()});school.teachers.find(t=>t.id===teacherId).classIds.push(id);school.classId=id;}document.getElementById('adminNewClass').value=''});
document.getElementById('createInvitation').onclick=()=>adminOperation(async()=>{if(!canAdminSchool()||!activeSchoolId())throw new Error('בחרו בית ספר מורשה.');const email=document.getElementById('inviteEmail').value.trim().toLowerCase(),invite_role=document.getElementById('inviteRole').value;if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw new Error('נדרש אימייל תקין.');if(invite_role==='manager'&&role!=='admin')throw new Error('רק אדמין יכול להזמין מנהל.');const class_id=document.getElementById('inviteClass').value||null,student_id=invite_role==='parent'?document.getElementById('inviteStudent').value:null;if(invite_role==='student'&&!class_id)throw new Error('בחרו כיתה לתלמיד.');if(invite_role==='parent'&&!student_id)throw new Error('בחרו את הילד שאליו יקושר ההורה.');const invite={school_id:activeSchoolId(),class_id,student_id,invite_role,email,created_by:adminId()};if(cloud.ready)await cloudResult(cloud.client.from('school_invitations').insert(invite));else{localInvitations.push({...invite,id:crypto.randomUUID(),token:crypto.randomUUID(),status:'pending',expires_at:new Date(Date.now()+7*86400000).toISOString()});saveLocalInvites()}document.getElementById('inviteEmail').value=''});
renderAdmin();
